        # Diagonals (only if they were 0)
        for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
            rr, cc = sr + dr, sc + dc
            if 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 0:
                    result[rr][cc] = color

    return result

